// Reference solution
function pathDelay(bits, hops) {
  var t = 0;
  for (var i = 0; i < hops.length; i++) t += bits / hops[i].bps * 1000 + hops[i].km * 1000 / 2e8 * 1000;
  return Math.round(t * 1000) / 1000;
}
